            font-weight: 600;
            text-decoration: none;
            display: inline-block;
            margin: 15px 0;
            box-shadow: 0 8px 20px rgba(240, 147, 251, 0.3);
            transition: transform 0.3s;
        }

        .download-btn:hover {
            transform: translateY(-2px);
        }

        .urgent-note {
            background: #fed7d7;
            border-left: 4px solid #e53e3e;
            padding: 15px;
            border-radius: 0 8px 8px 0;
            margin: 20px 0;
        }

