            background: #fff5cd;
            border: 2px solid #f6e05e;
            padding: 20px;
            border-radius: 10px;
            text-align: center;
            margin: 20px 0;
        }

        .referral-reward .reward-icon {
            font-size: 2rem;
            margin-bottom: 10px;
            color: #d69e2e;
        }

        .footer {
            background: #2d3748;
            color: white;
            padding: 25px;
            text-align: center;
        }

        .footer a {
            color: #81e6d9;
            text-decoration: none;
        }

